def transform(grid):
 h=len(grid); w=len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   color=grid[r][c]; pts=[]; stack=[(r,c)]; seen.add((r,c))
   while stack:
    y,x=stack.pop(); pts.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=y+dy,x+dx
      if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
       seen.add((ny,nx)); stack.append((ny,nx))
   comps.append((color,sorted(pts)))
 out=[[0]*w for _ in range(h)]
 for i,(color,a) in enumerate(comps):
  for color2,b in comps[i+1:]:
   if color!=color2: continue
   best=None; path=[]
   for y,x in a:
    for z,t in b:
     if y==z:
      p=[(y,k) for k in range(min(x,t)+1,max(x,t))]
     elif x==t:
      p=[(k,x) for k in range(min(y,z)+1,max(y,z))]
     else: continue
     if best is None or len(p)<best:
      best=len(p); path=p
   for y,x in path: out[y][x]=5
 return out

